  const execution = executeWorkflow(failing, {});
  assert.equal(execution.status, 'invalid_input');
  assert.deepEqual(execution.context.input, {});
  assert.deepEqual(execution.trace.map(n => n.nodeId), ['start', 'collect']);
});

