  { id: 'a', type: 'trigger', next: 'c1' },
  { id: 'c1', type: 'condition', condition: { all: [{field:'k', operator:'exists'}] }, then: 'end1', else: 'c2' },
  { id: 'c2', type: 'condition', condition: { any: [{ field: 'z', operator: 'bogus', value: 1 }] }, then: 'end1', else: 'end2' },
  { id: 'end1', type: 'end', result: 1 },
  { id: 'end2', type: 'end', result: 2 },
]};
try { validateWorkflow(wf); console.log('FAIL: should throw'); } catch (e) { console.log('unreachable node checked:', e.message); }

// 33-deep nesting reports position
let c = { field: 'x', operator: 'exists' };
for (let i = 1; i < 33; i++) c = { not: c };
const wf2 = { id: 'd', entry: 'a', nodes: [
  { id: 'a', type: 'trigger', next: 'c' },
  { id: 'c', type: 'condition', condition: c, then: 'e1', else: 'e2' },
  { id: 'e1', type: 'end', result: 1 }, { id: 'e2', type: 'end', result: 2 },
]};
try { validateWorkflow(wf2); console.log('FAIL: depth'); } catch (e) { console.log('depth:', e.message); }

// end-to-end nested compound + valueField
const wf3 = { id: 'n', entry: 'a', nodes: [
  { id: 'a', type: 'trigger', next: 'c' },
  { id: 'c', type: 'condition', condition: { not: { any: [
    { field: 'age', operator: 'lte', value: 17 },
    { field: 'blocked', operator: 'eq', value: true },
  ] } }, then: 'go', else: 'stop' },
  { id: 'go', type: 'end', result: 'go' },
  { id: 'stop', type: 'end', result: 'stop' },
]};
